using System;using System.Runtime.InteropServices;using System.Windows.Automation;
public static class OwnedSelectionPageInput {
 [StructLayout(LayoutKind.Sequential)]public struct POINT{public int x,y;}
 [StructLayout(LayoutKind.Sequential)]public struct MOUSE{public int x,y;public uint data,flags,time;public UIntPtr extra;}
 [StructLayout(LayoutKind.Sequential)]public struct KEY{public ushort vk,scan;public uint flags,time;public UIntPtr extra;}
 [StructLayout(LayoutKind.Explicit,Size=32)]public struct UNION{[FieldOffset(0)]public MOUSE mouse;[FieldOffset(0)]public KEY key;}
 [StructLayout(LayoutKind.Sequential)]public struct INPUT{public uint type;public UNION data;}
 [DllImport("user32.dll",SetLastError=true)]static extern uint SendInput(uint n,INPUT[] events,int size);
 [DllImport("user32.dll")]static extern int GetSystemMetrics(int n);
 [DllImport("user32.dll")]static extern bool GetCursorPos(out POINT p);
 [DllImport("user32.dll")]static extern bool GetPhysicalCursorPos(out POINT p);
 [DllImport("user32.dll")]static extern IntPtr SetThreadDpiAwarenessContext(IntPtr c);
 [DllImport("user32.dll")]static extern IntPtr GetThreadDpiAwarenessContext();
 [DllImport("user32.dll")]static extern int GetAwarenessFromDpiAwarenessContext(IntPtr c);
 [DllImport("user32.dll")]static extern IntPtr GetForegroundWindow();
 [DllImport("user32.dll")]static extern bool SetForegroundWindow(IntPtr w);
 [DllImport("user32.dll")]static extern IntPtr WindowFromPoint(POINT point);
 [DllImport("user32.dll")]static extern IntPtr GetAncestor(IntPtr window,uint flags);
 [DllImport("user32.dll")]static extern uint GetWindowThreadProcessId(IntPtr window,out uint pid);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern int GetWindowText(IntPtr window,System.Text.StringBuilder title,int count);
 static void Emit(INPUT i){if(SendInput(1,new[]{i},Marshal.SizeOf<INPUT>())!=1)throw new InvalidOperationException("SendInput failed");}
 static void KeyEvent(ushort vk,bool down){Emit(new INPUT{type=1,data=new UNION{key=new KEY{vk=vk,flags=down?0u:2u}}});}
 static void Mouse(uint flags,uint data){Emit(new INPUT{type=0,data=new UNION{mouse=new MOUSE{flags=flags,data=data}}});}
 static void Move(int x,int y){int l=GetSystemMetrics(76),t=GetSystemMetrics(77),w=GetSystemMetrics(78),h=GetSystemMetrics(79);if(w<=1||h<=1||x<l||x>=l+w||y<t||y>=t+h)throw new InvalidOperationException("Display bounds failed");Emit(new INPUT{type=0,data=new UNION{mouse=new MOUSE{x=(int)Math.Round((x-l)*65535d/(w-1)),y=(int)Math.Round((y-t)*65535d/(h-1)),flags=0xC001}}});}



 public static string Run(string app,string mode){
  if(!System.Text.RegularExpressions.Regex.IsMatch(app,@"\\DBMV-Isolated-preflight-selectionpage-[0-9a-f]{32}\\app$"))throw new InvalidOperationException("Owned Selection path required");
  var modes=new[]{"bulk-toggle","bulk-label","focus-mapping","expand-data","category-data","search-orders","deselect","bulk","empty-hover","empty-leave","mapping","clear-search","search-none","escape","passive","category-trial","category-schema","trial","back","language","mount","motion","focus-search","next","scroll-top","scroll-table","scroll-bottom"};if(Array.IndexOf(modes,mode)<0)throw new InvalidOperationException("Fixed Selection mode required");
  var oldDpi=SetThreadDpiAwarenessContext(new IntPtr(-4));bool down=false,ctrl=false;POINT old;GetPhysicalCursorPos(out old);AutomationElement window=null;string phase="inventory",transport=System.IO.Path.Combine(app,"selectionpage-native-"+mode+"-transport.txt");System.IO.File.WriteAllText(transport,"begin="+DateTime.UtcNow.ToString("o")+" mode="+mode+"\n");
  try{
   var launch=System.IO.File.ReadAllText(System.IO.Path.Combine(app,"selectionpage-launch.json"));var pid=System.Text.RegularExpressions.Regex.Match(launch,"\\\"pid\\\"\\s*:\\s*(\\d+)");if(!pid.Success)throw new InvalidOperationException("Fresh PID absent");var proc=System.Diagnostics.Process.GetProcessById(int.Parse(pid.Groups[1].Value));if(!proc.MainModule.FileName.Equals(System.IO.Path.Combine(app,"ReplicaProbe.exe"),StringComparison.OrdinalIgnoreCase)||proc.MainWindowHandle==IntPtr.Zero)throw new InvalidOperationException("Exact PID/path/window absent");window=AutomationElement.FromHandle(proc.MainWindowHandle);if(window.Current.Name!="Replica SelectionPage verification")throw new InvalidOperationException("Exact title absent");
   Func<Func<AutomationElement,bool>,AutomationElement> find=predicate=>{var stack=new System.Collections.Generic.Stack<Tuple<AutomationElement,int>>();stack.Push(Tuple.Create(window,0));int visits=0;var seen=new System.Collections.Generic.HashSet<string>();while(stack.Count>0&&visits++<900){var entry=stack.Pop();var e=entry.Item1;if(!seen.Add(string.Join(",",e.GetRuntimeId())))continue;if(predicate(e))return e;if(entry.Item2>=24||e.Current.ControlType==ControlType.Button||e.Current.ControlType==ControlType.CheckBox||e.Current.ControlType==ControlType.Text||e.Current.ControlType==ControlType.Edit)continue;var child=TreeWalker.ControlViewWalker.GetFirstChild(e);int count=0;while(child!=null&&count++<80){stack.Push(Tuple.Create(child,entry.Item2+1));child=TreeWalker.ControlViewWalker.GetNextSibling(child);}}return null;};
   var frame=window.Current.BoundingRectangle;SetForegroundWindow(proc.MainWindowHandle);System.Threading.Thread.Sleep(120);Action guard=()=>{if(GetForegroundWindow()!=proc.MainWindowHandle)throw new InvalidOperationException("Own foreground lost");};guard();AutomationElement target=null;
   if(Array.IndexOf(new[]{"language","mount","motion","focus-search","next","scroll-top","scroll-table","scroll-bottom"},mode)>=0){target=find(e=>e.Current.AutomationId=="SelectionPage-"+mode);if(target==null||target.Current.Name!=mode||!target.Current.IsEnabled||target.Current.IsOffscreen)throw new InvalidOperationException("Exact setup utility absent");phase="utility";((InvokePattern)target.GetCurrentPattern(InvokePattern.Pattern)).Invoke();}
   else if(mode=="bulk-toggle"){phase="toggle-provider";target=find(e=>e.Current.AutomationId=="table-all"&&e.Current.ControlType==ControlType.CheckBox);if(target==null||!target.Current.IsEnabled||target.Current.IsOffscreen)throw new InvalidOperationException("Own bulk Toggle target absent");((TogglePattern)target.GetCurrentPattern(TogglePattern.Pattern)).Toggle();}
   else if(mode=="focus-mapping"){phase="focus-provider";target=find(e=>e.Current.AutomationId=="Selection-mapping-demo.orders");if(target==null||!target.Current.IsEnabled||target.Current.IsOffscreen)throw new InvalidOperationException("Own mapping focus target absent");target.SetFocus();}
   else if(mode=="empty-leave"){phase="leave";Move((int)frame.Left+10,(int)frame.Top+50);}
   else if(mode=="escape"){phase="key-guard";target=AutomationElement.FocusedElement;if(target==null||target.Current.AutomationId!="table-search"||target.Current.ProcessId!=proc.Id)throw new InvalidOperationException("Search key predecessor absent");KeyEvent(27,true);KeyEvent(27,false);}
   else{
    if(mode=="expand-data")target=find(e=>e.Current.ControlType==ControlType.Button&&(e.Current.Name.StartsWith("데이터",StringComparison.Ordinal)||e.Current.Name.StartsWith("Data",StringComparison.Ordinal)));else if(mode=="category-data")target=find(e=>e.Current.ControlType==ControlType.CheckBox&&(e.Current.Name=="데이터 검사 선택"||e.Current.Name=="Data check selection"));else if(mode=="deselect")target=find(e=>e.Current.AutomationId=="Selection-clear-tables");else if(mode=="bulk-label")target=find(e=>e.Current.ControlType==ControlType.Text&&(e.Current.Name=="검색 결과 전체 선택"||e.Current.Name=="Select all matching tables"));else if(mode=="bulk")target=find(e=>e.Current.AutomationId=="table-all");else if(mode=="empty-hover")target=find(e=>e.Current.ControlType==ControlType.DataItem&&(e.Current.Name.StartsWith("검색된 테이블이 없습니다.",StringComparison.Ordinal)||e.Current.Name.StartsWith("No tables match.",StringComparison.Ordinal)));else if(mode=="mapping")target=find(e=>e.Current.AutomationId=="Selection-mapping-demo.orders");else if(mode=="clear-search")target=find(e=>e.Current.ControlType==ControlType.Button&&(e.Current.Name=="테이블 검색 지우기"||e.Current.Name=="Clear table search"));else if(mode=="search-none"||mode=="search-orders")target=find(e=>e.Current.AutomationId=="table-search");else if(mode=="passive")target=find(e=>e.Current.ControlType==ControlType.Text&&(e.Current.Name.StartsWith("사용자·역할·소유자는",StringComparison.Ordinal)||e.Current.Name.StartsWith("Users, roles and owners",StringComparison.Ordinal)));else if(mode=="category-trial")target=find(e=>e.Current.ControlType==ControlType.CheckBox&&(e.Current.Name=="별도 DB 동작 시험 검사 선택"||e.Current.Name=="Behavior tests in a separate DB check selection"));else if(mode=="category-schema")target=find(e=>e.Current.ControlType==ControlType.CheckBox&&(e.Current.Name=="구조·제약 검사 선택"||e.Current.Name=="Schema & constraints check selection"));else if(mode=="trial")target=find(e=>e.Current.AutomationId=="TrialPreparation-prepare");else if(mode=="back")target=find(e=>e.Current.AutomationId=="Footer-back");
    if(target==null)throw new InvalidOperationException("Exact target missing "+mode);phase="bounds";var b=target.Current.BoundingRectangle;var name=target.Current.Name;if(b.Width<=0||b.Height<=0||!target.Current.IsEnabled||target.Current.IsOffscreen||string.IsNullOrEmpty(name))throw new InvalidOperationException("Target bounds/name/enabled/visible failed");int x=(int)Math.Round(mode=="passive"?b.Left+20:b.Left+b.Width/2),y=(int)Math.Round(b.Top+b.Height/2);if(!frame.Contains(new System.Windows.Point(x,y)))throw new InvalidOperationException("Point outside window");phase="physical-hit";Move(x,y);System.Threading.Thread.Sleep(60);guard();POINT actual;if(!GetPhysicalCursorPos(out actual)||Math.Abs(actual.x-x)>1||Math.Abs(actual.y-y)>1)throw new InvalidOperationException("Physical cursor mismatch");var root=GetAncestor(WindowFromPoint(actual),2);uint hitPid;GetWindowThreadProcessId(root,out hitPid);var title=new System.Text.StringBuilder(512);GetWindowText(root,title,title.Capacity);var fresh=target.Current.BoundingRectangle;if(root!=proc.MainWindowHandle||hitPid!=proc.Id||title.ToString()!="Replica SelectionPage verification"||!fresh.Contains(new System.Windows.Point(actual.x,actual.y))||target.Current.Name!=name||!target.Current.IsEnabled||target.Current.IsOffscreen)throw new InvalidOperationException("Fresh own Win32 hit/target failed");System.IO.File.AppendAllText(transport,"frame="+frame+" requested="+x+","+y+" actual="+actual.x+","+actual.y+" root="+root+" pid="+hitPid+" path="+proc.MainModule.FileName+" title="+title+" target="+target.Current.AutomationId+" name="+name+"\n");if(mode!="empty-hover"){phase="down";Mouse(2,0);down=true;System.Threading.Thread.Sleep(25);guard();Mouse(4,0);down=false;}
    if(mode=="search-none"||mode=="search-orders"){System.Threading.Thread.Sleep(100);var focus=AutomationElement.FocusedElement;if(focus==null||focus.Current.AutomationId!="table-search")throw new InvalidOperationException("Typing predecessor missing");KeyEvent(17,true);ctrl=true;KeyEvent(65,true);KeyEvent(65,false);KeyEvent(17,false);ctrl=false;foreach(char c in(mode=="search-none"?"missing-table":"orders")){Emit(new INPUT{type=1,data=new UNION{key=new KEY{scan=c,flags=4}}});Emit(new INPUT{type=1,data=new UNION{key=new KEY{scan=c,flags=6}}});}}
   }
   System.Threading.Thread.Sleep(650);guard();phase="post";var f=AutomationElement.FocusedElement;System.IO.File.AppendAllText(transport,"postFocus="+(f==null?"none":f.Current.AutomationId)+"\n");using(var file=new System.IO.FileStream(System.IO.Path.Combine(app,"selectionpage-input.json"),System.IO.FileMode.Open,System.IO.FileAccess.Read,System.IO.FileShare.ReadWrite|System.IO.FileShare.Delete))using(var reader=new System.IO.StreamReader(file))return reader.ReadToEnd();
  }catch(Exception e){System.IO.File.AppendAllText(transport,"failure-phase="+phase+" error="+e+"\n");throw;}finally{if(ctrl)KeyEvent(17,false);if(down)Mouse(4,0);if(window!=null&&GetForegroundWindow().ToInt64()==window.Current.NativeWindowHandle)Move(old.x,old.y);if(oldDpi!=IntPtr.Zero)SetThreadDpiAwarenessContext(oldDpi);}
 }
}
